#include <stdlib.h>
#include <string.h>

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg) {
    struct xc2028_priv *cfg = (struct xc2028_priv *)priv_cfg;
    int result = 0;

    if (!fe || !cfg) {
        return -1;
    }

    if (!fe->ops->lock_mutex || !fe->ops->unlock_mutex) {
        return -1;
    }

    fe->ops->lock_mutex(fe);

    if (cfg->firmware_name && fe->firmware_name && strcmp(cfg->firmware_name, fe->firmware_name) != 0) {
        free(fe->firmware_name);
        fe->firmware_name = NULL;
    }

    if (cfg->firmware_name) {
        fe->firmware_name = strdup(cfg->firmware_name);
        if (!fe->firmware_name) {
            fe->ops->unlock_mutex(fe);
            return -1;
        }
    }

    if (fe->state == XC2028_STATE_NO_FIRMWARE) {
        result = fe->ops->request_firmware(fe);
        if (result < 0) {
            fe->ops->unlock_mutex(fe);
            return result;
        }
    }

    fe->ops->unlock_mutex(fe);
    return result;
}
